            sunGlow.addColorStop(0.3, '#fde047');
            sunGlow.addColorStop(0.7, 'rgba(254,240,138,0.3)');
            sunGlow.addColorStop(1, 'rgba(56,189,248,0)');
            g.fillStyle = sunGlow;
            g.fillRect(300, 0, 424, 340);
            // Floating island silhouettes
